/**
 * generated by stackra gen from stackra.config.ts (area), src/config/env.config.ts (EnvConfig), the
 * producers' VersioningConfig and the inferred consumed services — do not edit
 * Purpose: the per-request public clients for the Worker: one caller over HTTP to the gateway's
 *          public area, carrying the request's locale and market so the services localise and price
 *          without a second round trip, and forwarding three facts of the visitor's request: its
 *          W3C `traceparent` (one trace from the edge to the services), the visitor's address
 *          signed with an HMAC under `GATEWAY_VISITOR_SIGNING_KEY` (the gateway verifies the
 *          signature before it uses the address, so a client cannot set it) and its `Sec-Purpose`
 *          header (a prefetch or prerender is not a visit). Every call pins `Stackra-Version` to
 *          `apiVersion`.
 * Boundary: anonymous callers only: no session, no token. Every public call is GET or idempotent,
 *           so the transport retries once on a network failure, never on a refusal. The route
 *           adapters expose it as `ctx.query` and `ctx.action`, through the context key of
 *           `../context.ts`. Server only: no route module imports this file.
 * Runtime: worker
 */
import { createPublicClients, RetryOn, type PublicClients } from "@stackra/clients/server";
import { forwardedFacts } from "@stackra/clients/worker";
import { ApiArea } from "@stackra/contracts";
import type { Locale } from "@stackra/i18n";
import type { EnvConfig } from "#src/config/env.config";

export type { PublicClients };

/**
 * The newest date listed in the producers' VersioningConfig at gen time; identical in every app of
 * the workspace.
 */
export const apiVersion = "2027-03-01" as const;

/** Per-request facts the gateway reads from headers. Omitted on the redirect lookup and 404 log. */
export interface PublicClientOptions {
  /** The request's locale, sent as `Accept-Language`. */
  readonly locale?: Locale;

  /** The site's market key, sent as `Stackra-Market`. */
  readonly market?: string;
}

/** One client set per request, bound to the visitor's request it forwards. */
export function publicClients(
  env: EnvConfig,
  request: Request,
  options: PublicClientOptions = {},
): PublicClients {
  return createPublicClients({
    baseUrl: env.apiUrl,
    area: ApiArea.Public,
    version: apiVersion,
    ...(options.locale ? { locale: options.locale } : {}),
    ...(options.market ? { market: options.market } : {}),
    // `traceparent`, `Stackra-Visitor` (address, time and HMAC) and `Sec-Purpose`
    forward: forwardedFacts(request, { signingKey: env.visitorSigningKey }),
    retry: {
      attempts: 2,
      on: RetryOn.Network,
    },
  });
}
